#include "ClientCommon.h"

#include <cppgate/Client/HttpClient.h>

#include <boost/asio/buffer.hpp>
#include <boost/url/parse.hpp>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <stdexcept>
#include <system_error>

namespace gtvr::detail {

    // sources/Client/CaBundle.cpp, generated by tools/update_ca_bundle.py
    extern const char* const ca_bundle_parts[];
    extern const std::size_t ca_bundle_part_count;

    namespace {

        namespace ssl = boost::asio::ssl;

        // Where operating systems keep their CA bundle (the list Go's crypto/x509 uses)
        constexpr const char* system_ca_files[] = {
            "/etc/ssl/certs/ca-certificates.crt",                   // Debian, Ubuntu, Gentoo, Arch
            "/etc/pki/tls/certs/ca-bundle.crt",                     // Fedora, RHEL 6
            "/etc/ssl/ca-bundle.pem",                               // openSUSE
            "/etc/pki/tls/cacert.pem",                              // OpenELEC
            "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem",    // CentOS, RHEL 7
            "/etc/ssl/cert.pem",                                    // macOS, Alpine, FreeBSD, OpenBSD
            "/usr/local/etc/ssl/cert.pem",                          // FreeBSD ports
        };

        bool fileExists(const char* path)
        {
            std::error_code ec;
            return std::filesystem::is_regular_file(path, ec);
        }

        bool dirExists(const char* path)
        {
            std::error_code ec;
            return std::filesystem::is_directory(path, ec);
        }

        // True if a system store was found
        bool loadSystemCas(ssl::context& tls)
        {
            // OpenSSL's own defaults point where OpenSSL was built (with Conan, a cache folder),
            // but this is also what reads $SSL_CERT_FILE and $SSL_CERT_DIR
            tls.set_default_verify_paths();

            const char* env_file = std::getenv("SSL_CERT_FILE");
            const char* env_dir = std::getenv("SSL_CERT_DIR");
            bool found = (env_file && fileExists(env_file)) || (env_dir && dirExists(env_dir));

            for (const char* path : system_ca_files)
            {
                if (fileExists(path))
                {
                    tls.load_verify_file(path);
                    return true;
                }
            }

            return found;
        }

    }

    boost::system::result<Target> parseUrl(std::string_view url, UrlKind kind)
    {
        auto parsed = boost::urls::parse_uri(url);
        if (!parsed || !parsed->has_authority() || parsed->host().empty())
            return make_error_code(client_error::invalid_url);

        const auto& u = *parsed;
        Target t;

        auto plain  = kind == UrlKind::http ? boost::urls::scheme::http  : boost::urls::scheme::ws;
        auto secure = kind == UrlKind::http ? boost::urls::scheme::https : boost::urls::scheme::wss;

        if (u.scheme_id() == secure)
            t.tls = true;
        else if (u.scheme_id() != plain)
            return make_error_code(client_error::unsupported_scheme);

        t.host = u.host_type() == boost::urls::host_type::ipv6 ? u.host_ipv6_address().to_string() : std::string(u.host());
        t.port = u.has_port() ? std::string(u.port()) : (t.tls ? "443" : "80");

        bool default_port = !u.has_port() || t.port == (t.tls ? "443" : "80");
        t.host_header = std::string(u.encoded_host_and_port());
        if (default_port && u.has_port())
            t.host_header = std::string(u.encoded_host());

        t.target = u.encoded_path().empty() ? "/" : std::string(u.encoded_path());
        if (u.has_query())
            t.target += "?" + std::string(u.encoded_query());

        t.key = std::string(u.scheme()) + "://" + t.host + ":" + t.port;
        return t;
    }

    void configureClientTls(ssl::context& tls, const ClientTlsOptions& options, const char* who)
    {
        tls.set_options(ssl::context::default_workarounds | ssl::context::no_sslv2 | ssl::context::no_sslv3
                      | ssl::context::no_tlsv1 | ssl::context::no_tlsv1_1);
        tls.set_verify_mode(options.verify_peer ? ssl::verify_peer : ssl::verify_none);

        bool trusted = false;

        if (options.use_bundled_cas)
        {
            for (std::size_t i = 0; i < ca_bundle_part_count; ++i)
                tls.add_certificate_authority(boost::asio::buffer(ca_bundle_parts[i], std::strlen(ca_bundle_parts[i])));
            trusted = true;
        }

        if (options.use_system_cas)
            trusted |= loadSystemCas(tls);

        for (const auto& file : options.extra_ca_files)
        {
            tls.load_verify_file(file);
            trusted = true;
        }

        for (const auto& dir : options.extra_ca_dirs)
        {
            // OpenSSL only reads the directory when it needs a certificate: check it now
            if (!dirExists(dir.c_str()))
                throw boost::system::system_error(std::make_error_code(std::errc::no_such_file_or_directory), std::string(who) + ": extra_ca_dirs: " + dir);
            tls.add_verify_path(dir);
            trusted = true;
        }

        for (const auto& pem : options.extra_ca_pem)
        {
            tls.add_certificate_authority(boost::asio::buffer(pem));
            trusted = true;
        }

        // Every HTTPS / WSS connection would fail: say it now
        if (options.verify_peer && !trusted)
            throw std::invalid_argument(std::string(who) + (options.use_system_cas
                ? ": use_system_cas found no CA store; set SSL_CERT_FILE, or use extra_ca_files / use_bundled_cas"
                : ": no trusted CA source; enable use_bundled_cas or use_system_cas, or give extra_ca_*"));
    }

}//namespace gtvr::detail
